mapper.select:
SELECT b.id AS id, u.full_name AS specialistName, sp.level AS specialistTitle, sp.avatar_url AS specialistAvatar, TIMESTAMP(ts.slot_date, ts.start_time) AS startTime, TIMESTAMP(ts.slot_date, ts.end_time) AS endTime, TIMESTAMPDIFF(MINUTE, ts.start_time, ts.end_time) AS duration, b.status AS status, b.price AS amount FROM bookings b JOIN time_slots ts ON b.slot_id = ts.id JOIN specialist_profiles sp ON b.specialist_id = sp.id JOIN users u ON sp.user_id = u.id WHERE b.customer_id = #{customerId}
AND b.status = #{query.status}
AND TIMESTAMP(ts.slot_date, ts.start_time) > NOW()
AND (TIMESTAMP(ts.slot_date, ts.start_time) <= NOW() OR b.status IN ('COMPLETED', 'CANCELLED'))
ORDER BY ts.slot_date ASC, ts.start_time ASC
ORDER BY ts.slot_date DESC, ts.start_time DESC
